use axum::{extract::{Multipart, Path, State}, http::StatusCode};
use std::path::PathBuf;

use crate::AppState;

pub async fn upload_avatar(
    State(state): State<AppState>,
    Path(user_id): Path<i64>,
    mut form: Multipart,
) -> Result<StatusCode, StatusCode> {
    while let Some(field) = form.next_field().await.map_err(|_| StatusCode::BAD_REQUEST)? {
        if field.name() != Some("avatar") {
            continue;
        }
        let bytes = field.bytes().await.map_err(|_| StatusCode::BAD_REQUEST)?;
        let dir = PathBuf::from(&state.media_root).join("avatars");
        std::fs::create_dir_all(&dir).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        std::fs::write(dir.join(format!("{user_id}.png")), &bytes)
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        return Ok(StatusCode::NO_CONTENT);
    }
    Err(StatusCode::BAD_REQUEST)
}

