pub async fn publish_with_retry(&self, event: &OutboundEvent) -> Result<(), PublishError> {
    let mut delay_ms = 200;
    for attempt in 1..=5 {
        match self.producer.send(event.topic(), event.payload()).await {
            Ok(_) => return Ok(()),
            Err(e) if attempt < 5 => {
                tracing::warn!(attempt, error = %e, "publish failed, retrying");
                std::thread::sleep(std::time::Duration::from_millis(delay_ms));
                delay_ms *= 2;
            }
            Err(e) => return Err(PublishError::Exhausted(e)),
        }
    }
    unreachable!()
}

