pub async fn accept_loop(listener: TcpListener, mut control: mpsc::Receiver<Control>) -> std::io::Result<()> {
    loop {
        tokio::select! {
            accepted = listener.accept() => {
                let (socket, peer) = accepted?;
                tracing::debug!(%peer, "accepted connection");
                handle_connection(socket).await;
            }
            cmd = control.recv() => match cmd {
                Some(Control::Drain) | None => break,
                Some(Control::Ping(reply)) => { let _ = reply.send(()); }
            },
        }
    }
    Ok(())
}

