pub async fn fetch_all(client: &reqwest::Client, urls: Vec<String>) -> Vec<Result<String, reqwest::Error>> {
    let mut set = JoinSet::new();
    for url in urls {
        let client = client.clone();
        set.spawn(async move { client.get(&url).send().await?.text().await });
    }
    let mut out = Vec::new();
