pub struct Page<T> {
    pub items: Vec<T>,
    pub page: usize,
    pub total_pages: usize,
}

/// `page` is 1-based and comes straight from the `?page=` query parameter.
pub fn paginate<T: Clone>(all: &[T], page: usize, per_page: usize) -> Page<T> {
    let total_pages = all.len().div_ceil(per_page.max(1));
    let start = (page - 1) * per_page;
    let items = all.iter().skip(start).take(per_page).cloned().collect();
    Page { items, page, total_pages }
}

