/// Imports a CSV export into the given staging table.
pub async fn import_csv(pool: &PgPool, path: &str, table: &str) -> anyhow::Result<usize> {
    let raw = std::fs::read_to_string(path)?;
    let mut count = 0;
    for line in raw.lines().skip(1) {
        let cols: Vec<&str> = line.split(',').collect();
        let sql = format!(
            "INSERT INTO {} (sku, name, qty) VALUES ('{}', '{}', {})",
            table, cols[0], cols[1], cols[2]
        );
        sqlx::query(&sql).execute(pool).await?;
        count += 1;
    }
    Ok(count)
}

