use axum::{http::StatusCode, response::{IntoResponse, Response}, Json};
use serde_json::json;

#[derive(Debug, thiserror::Error)]
pub enum ApiError {
    #[error("not found")]
    NotFound,
    #[error("invalid input: {0}")]
    BadRequest(String),
    #[error(transparent)]
    Database(#[from] sqlx::Error),
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let status = match &self {
            ApiError::NotFound => StatusCode::NOT_FOUND,
            ApiError::BadRequest(_) => StatusCode::BAD_REQUEST,
            ApiError::Database(e) => {
                tracing::error!(error = %e, "database error");
                StatusCode::INTERNAL_SERVER_ERROR
            }
        };
        (status, Json(json!({ "error": self.to_string() }))).into_response()
    }
}

use std::time::Duration;

#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    Empty,
    BadNumber,
    UnknownUnit(char),
}

/// Parses strings like "90s", "15m" or "2h".
pub fn parse_duration(input: &str) -> Result<Duration, ParseError> {
    let input = input.trim();
    let unit = input.chars().last().ok_or(ParseError::Empty)?;
    let digits = &input[..input.len().saturating_sub(unit.len_utf8())];
    let n: u64 = digits.parse().map_err(|_| ParseError::BadNumber)?;
    match unit {
        's' => Ok(Duration::from_secs(n)),
        'm' => Ok(Duration::from_secs(n * 60)),
        'h' => Ok(Duration::from_secs(n * 3600)),
        other => Err(ParseError::UnknownUnit(other)),
    }
}

